// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceMermanTextMeasurer {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceMermanTextMeasurer = UniffiVTableCallbackInterfaceMermanTextMeasurer(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeMermanTextMeasurer.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface MermanTextMeasurer: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeMermanTextMeasurer.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface MermanTextMeasurer: handle missing in uniffiClone")
            }
        },
        measure: { (
            uniffiHandle: UInt64,
            request: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> MermanTextMeasureResult? in
                guard let uniffiObj = try? FfiConverterTypeMermanTextMeasurer.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.measure(
                     request: try FfiConverterTypeMermanTextMeasureRequest_lift(request)
                )
            }


            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionTypeMermanTextMeasureResult.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeMermanError_lower
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
